const STORAGE_KEY='diario-de-bordo-entries',form=document.querySelector('#entry-form'),titleInput=document.querySelector('#entry-title'),descriptionInput=document.querySelector('#entry-description'),dateInput=document.querySelector('#entry-date'),entriesList=document.querySelector('#entries-list'),emptyState=document.querySelector('#empty-state'),entryCount=document.querySelector('#entry-count'),entryNumber=document.querySelector('#entry-number'),sortButton=document.querySelector('#sort-button'),installButton=document.querySelector('#install-button'),connectionStatus=document.querySelector('#connection-status');let entries=loadEntries(),newestFirst=true,deferredInstallPrompt;function loadEntries(){try{return JSON.parse(localStorage.getItem(STORAGE_KEY))||[]}catch{return[]}}function saveEntries(){localStorage.setItem(STORAGE_KEY,JSON.stringify(entries))}function formatDate(dateString){const date=new Date(`${dateString}T12:00:00`);return{day:date.toLocaleDateString('pt-BR',{day:'2-digit'}),month:date.toLocaleDateString('pt-BR',{month:'short'}).replace('.',''),year:date.toLocaleDateString('pt-BR',{year:'numeric'})}}function renderEntries(){const sortedEntries=[...entries].sort((first,second)=>{const comparison=second.date.localeCompare(first.date)||second.createdAt-first.createdAt;return newestFirst?comparison:-comparison});entriesList.innerHTML=sortedEntries.map((entry,index)=>{const date=formatDate(entry.date);return`<article class="entry-card" style="animation-delay:${index*45}ms"><time class="entry-date" datetime="${entry.date}"><strong>${date.day}</strong>${date.month} ${date.year}</time><div><h3>${escapeHtml(entry.title)}</h3><p>${escapeHtml(entry.description)}</p></div><button class="delete-button" type="button" data-id="${entry.id}" aria-label="Remover entrada ${escapeHtml(entry.title)}">×</button></article>`}).join('');entryCount.textContent=`(${entries.length})`;entryNumber.textContent=String(entries.length+1).padStart(2,'0');emptyState.hidden=entries.length>0}function escapeHtml(value){return value.replace(/[&<>'"]/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#039;','"':'&quot;'}[character]))}function updateConnectionStatus(){const online=navigator.onLine;connectionStatus.classList.toggle('offline',!online);connectionStatus.innerHTML=`<span class="status-dot"></span>${online?'Online':'Offline'}`}form.addEventListener('submit',event=>{event.preventDefault();const newEntry={id:crypto.randomUUID?crypto.randomUUID():`${Date.now()}-${Math.random()}`,title:titleInput.value.trim(),description:descriptionInput.value.trim(),date:dateInput.value,createdAt:Date.now()};if(!newEntry.title||!newEntry.description||!newEntry.date)return;entries.push(newEntry);saveEntries();renderEntries();form.reset();dateInput.value=new Date().toISOString().slice(0,10);titleInput.focus()});entriesList.addEventListener('click',event=>{const deleteButton=event.target.closest('.delete-button');if(!deleteButton)return;entries=entries.filter(entry=>entry.id!==deleteButton.dataset.id);saveEntries();renderEntries()});sortButton.addEventListener('click',()=>{newestFirst=!newestFirst;sortButton.firstChild.textContent=newestFirst?'Mais recentes ':'Mais antigas ';renderEntries()});window.addEventListener('online',updateConnectionStatus);window.addEventListener('offline',updateConnectionStatus);window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;installButton.hidden=false});installButton.addEventListener('click',async()=>{if(!deferredInstallPrompt)return;deferredInstallPrompt.prompt();await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;installButton.hidden=true});if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('service-worker.js'));dateInput.value=new Date().toISOString().slice(0,10);updateConnectionStatus();renderEntries();